    exponent = inputs["exponent"]
    modulus = inputs["modulus"]

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, exp, mod):
        """Compute M^exp modulo mod using fast exponentiation"""
        if exp == 0:
            return [[1, 0], [0, 1]]  # Identity matrix
        if exp == 1:
            return [[M[0][0] % mod, M[0][1] % mod], [M[1][0] % mod, M[1][1] % mod]]

        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [row[:] for row in M]  # Copy matrix

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_pow(matrix, exponent, modulus)
    total = sum(sum(row) for row in result_matrix)
    return float(total)

